update order_user
set balance = balance - #{amount}, version = COALESCE(version, 0) + 1, update_time = NOW(3)
where id = #{userId} and balance >= #{amount}

update order_user
set balance = balance + #{amount}, version = COALESCE(version, 0) + 1, update_time = NOW(3)
where id = #{userId}

UPDATE order_user
SET balance = balance + #{amount},
    frozen_balance = frozen_balance - #{amount},
    task_progress = GREATEST(
        0,
        COALESCE(task_progress, 0) - #{progressDelta}
    ),
    version = COALESCE(version, 0) + 1,
    update_time = NOW(3)
WHERE id = #{userId}
  AND balance IS NOT NULL
  AND frozen_balance >= #{amount}

